CREATE TABLE IF NOT EXISTS public."tEventOfferSearchHistory" (
    "id"                         INT GENERATED BY DEFAULT AS IDENTITY,
    "eventId"                    INT NOT NULL,
    "pageId"                     INT NOT NULL,
    "positionId"                 INT NOT NULL,
    "eventOfferId"               INT NOT NULL,
    "offerNumber"                INT NOT NULL,
    "searchJson"                 TEXT,
    "userId"                     VARCHAR(100),
    "searchedAt"                 TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "tEventOfferSearchHistory_pkey" PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS idx_teventoffersearchhistory_lookup 
ON public."tEventOfferSearchHistory" ("eventId", "pageId", "positionId", "eventOfferId", "offerNumber");
